// Extract parameters from webhook body or test input
const body = $input.first().json.body || $input.first().json;

const job_description = body.job_description || `Senior Python & AI Engineer
Requirements:
- 5+ years of experience with Python, FastAPI, Django
- Hands-on experience with LLMs, LangChain, Google ADK, OpenAI
- Strong background in building REST APIs and microservices
- Proficiency in Docker, PostgreSQL, CI/CD
- B.S. in Computer Science or equivalent experience`;

const resume = body.resume || `Candidate Name: Alex Mercer
Email: alex.mercer@example.com
GitHub: https://github.com/octocat
Experience:
- Senior Backend Developer at TechCorp (2021 - Present, 3.5 yrs): Built scalable Python microservices using FastAPI & PostgreSQL. Integrated Gemini and OpenAI LLMs into internal workflows.
- Software Engineer at DataSoft (2019 - 2021, 2 yrs): Developed REST APIs with Django and Docker.
Education: B.S. Computer Science, State University (2019)`;

const github_username = body.github_username || "";
const gemini_api_key = body.gemini_api_key || process.env.GEMINI_API_KEY || "";
const model_name = body.model_name || process.env.MODEL_NAME || "gemini-2.5-flash";
const github_token = body.github_token || process.env.GITHUB_TOKEN || "";

return {
  json: {
    job_description,
    resume,
    github_username,
    gemini_api_key,
    model_name,
    github_token
  }
};

const prev = $('Prepare Input & API Keys').first().json;
const geminiResp = $input.first().json;

let rubricText = "";
if (geminiResp.candidates && geminiResp.candidates[0]?.content?.parts[0]?.text) {
  rubricText = geminiResp.candidates[0].content.parts[0].text;
} else if (geminiResp.error) {
  rubricText = "Error from Gemini API: " + (geminiResp.error.message || JSON.stringify(geminiResp.error));
} else {
  rubricText = "Unexpected Gemini API response format: " + JSON.stringify(geminiResp);
}

return {
  json: {
    ...prev,
    rubric: rubricText
  }
};

const prev = $('Parse Rubric Output').first().json;
const geminiResp = $input.first().json;

let resumeEvalText = "";
if (geminiResp.candidates && geminiResp.candidates[0]?.content?.parts[0]?.text) {
  resumeEvalText = geminiResp.candidates[0].content.parts[0].text;
} else if (geminiResp.error) {
  resumeEvalText = "Error evaluating resume: " + (geminiResp.error.message || JSON.stringify(geminiResp.error));
} else {
  resumeEvalText = "Unexpected response: " + JSON.stringify(geminiResp);
}

// Robust GitHub username extraction
let username = prev.github_username || "";
if (!username) {
  const match = prev.resume.match(/github\.com\/([a-zA-Z0-9_-]+)/i) || resumeEvalText.match(/github\.com\/([a-zA-Z0-9_-]+)/i);
  if (match && match[1]) {
    username = match[1];
  }
}

// Clean username (handle URLs, @, trailing slashes, query params)
if (username.includes("github.com/")) {
  const parts = username.split("github.com/");
  username = parts[parts.length - 1].split("/")[0].split("?")[0];
}
username = username.replace(/^@/, '').replace(/\/$/, '').trim();

return {
  json: {
    ...prev,
    resume_evaluation: resumeEvalText,
    github_username: username
  }
};

const prev = $('Parse Resume Evaluation').first().json;
const apiData = $input.first().json;

let githubValidationReport = {};

if (apiData.login) {
  githubValidationReport = {
    status: "PASSED",
    username: apiData.login,
    name: apiData.name || "Not provided",
    company: apiData.company || "Not provided",
    location: apiData.location || "Not provided",
    bio: apiData.bio || "Not provided",
    public_repos: apiData.public_repos || 0,
    followers: apiData.followers || 0,
    following: apiData.following || 0,
    created_at: apiData.created_at || "",
    html_url: apiData.html_url || `https://github.com/${prev.github_username}`
  };
} else {
  githubValidationReport = {
    status: "FAILED",
    username: prev.github_username,
    error: apiData.message || "Account not found on GitHub API"
  };
}

return {
  json: {
    ...prev,
    github_validation: githubValidationReport
  }
};

const prev = $('Process GitHub API Data').first().json;
const geminiResp = $input.first().json;

let githubEvalText = "";
if (geminiResp.candidates && geminiResp.candidates[0]?.content?.parts[0]?.text) {
  githubEvalText = geminiResp.candidates[0].content.parts[0].text;
} else if (geminiResp.error) {
  githubEvalText = "Error evaluating GitHub: " + (geminiResp.error.message || JSON.stringify(geminiResp.error));
} else {
  githubEvalText = "Unexpected response: " + JSON.stringify(geminiResp);
}

return {
  json: {
    ...prev,
    github_evaluation: githubEvalText
  }
};

const prev = $('Parse Resume Evaluation').first().json;

return {
  json: {
    ...prev,
    github_validation: { status: "SKIPPED", reason: "No GitHub profile provided" },
    github_evaluation: "GitHub Evaluation Skipped (No GitHub profile URL or username provided)."
  }
};

const geminiResp = $input.first().json;

// Retrieve input data passed into Step 5
const prev = $node["Step 5: VerdictSynthesizer (LLM)"].input.item.json;

let verdictText = "";
if (geminiResp.candidates && geminiResp.candidates[0]?.content?.parts[0]?.text) {
  verdictText = geminiResp.candidates[0].content.parts[0].text;
} else if (geminiResp.error) {
  verdictText = "Error synthesizing verdict: " + (geminiResp.error.message || JSON.stringify(geminiResp.error));
} else {
  verdictText = "Unexpected response: " + JSON.stringify(geminiResp);
}

// Extract Decision (HIRE vs NO HIRE)
let decision = "UNKNOWN";
if (verdictText.includes("🟢 HIRE") || verdictText.includes("HIRE")) {
  decision = "HIRE";
} else if (verdictText.includes("🔴 NO HIRE") || verdictText.includes("NO HIRE")) {
  decision = "NO HIRE";
}

// Extract Score
const scoreMatch = verdictText.match(/COMPOSITE SCORE:\s*([\d\.]+\/10)/i);
const composite_score = scoreMatch ? scoreMatch[1] : "N/A";

// Extract Candidate Name
const candidateMatch = (prev.resume_evaluation || "").match(/CANDIDATE:\s*([^
]+)/i);
const candidate_name = candidateMatch ? candidateMatch[1].trim() : "Candidate";

return {
  json: {
    success: true,
    candidate_name,
    decision,
    composite_score,
    summary: {
      rubric: prev.rubric,
      resume_evaluation: prev.resume_evaluation,
      github_validation: prev.github_validation,
      github_evaluation: prev.github_evaluation,
      final_verdict: verdictText
    }
  }
};
